INSERT INTO public.track_tournament_result(id_tournament,id_user,id_record,time,rank,points,date_created,date_updated) SELECT $1,winner.id_user,winner.id,winner.time,1,1000,clock_timestamp(),clock_timestamp() FROM (SELECT DISTINCT ON(r.id_user) r.id_user,r.id,r.time FROM public.record r JOIN public."user" u ON u.id=r.id_user JOIN public.track_tournament t ON t.id=$1 WHERE r.id_level=t.id_level AND r.date_created>=t.start_at AND r.date_created<t.end_at AND r.record_eligible AND NOT u.banned ORDER BY r.id_user,r.time,r.id) winner ON CONFLICT(id_tournament,id_user) DO NOTHING
